#include <cstdio>
#include <cstring>
#include <cmath>
#include <cstdlib>
#include <vector>
#include <string>
#include <algorithm>
#include <queue>
#include <stack>
#include <deque>
#include <map>
#include <set>
#include <unordered_map>
#include <unordered_set>
#include <functional>
#include <numeric>
#include <sstream>
#include <iostream>
using namespace std;
int main(){int n;scanf("%d",&n);
vector<pair<long long,long long>>v(n);
for(int i=0;i<n;++i)scanf("%lld %lld",&v[i].first,&v[i].second);
sort(v.begin(),v.end());
priority_queue<long long,vector<long long>,greater<long long>>pq;
for(auto&pr:v){
if(!pq.empty()&&pq.top()<=pr.first)pq.pop();
pq.push(pr.second);}
printf("%d\n",(int)pq.size());return 0;}

